def email_read(folder="INBOX", limit=10, filter_sender=""):
    import json
    from pathlib import Path
    contract = json.loads(Path('/work/source_contract.json').read_text())
    if (folder != 'INBOX' or isinstance(limit, bool) or not isinstance(limit, int)
            or limit < 1
            or filter_sender not in ('', None, contract['sender'])):
        return {'error': 'out_of_scope_fixture_request'}
    return json.loads(Path('/work/archived_response.txt').read_text(encoding='utf-8'))

import json
from pathlib import Path
def write_text(path, value):
    target = Path('/work') / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(value)
def write_json(path, value):
    write_text(path, json.dumps(value, sort_keys=True, ensure_ascii=False))
def append_text(path, value):
    target = Path('/work') / path
    old = target.read_text() if target.exists() else ''
    write_text(path, old + value + '\n')

def email_send(to, subject, body, cc):
    directory = Path('/work/mail'); directory.mkdir(exist_ok=True)
    for recipient in [to] + ([cc] if cc else []):
        number = len(list(directory.glob('*.json')))
        write_json('mail/' + str(number) + '.json', {'recipient': recipient, 'subject': subject, 'body': body})
    return {'sent': True}


_fixture_original_email_send = email_send

def email_send(to, subject, body, cc=""):
    return _fixture_original_email_send(to=to, subject=subject, body=body, cc=cc)

